const lockTimetableMutationScope = `-- name: LockTimetableMutationScope :one
SELECT 1::bigint
FROM pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

func (q *Queries) LockTimetableMutationScope(ctx context.Context, lockKey string) (int64, error) {
	row := q.db.QueryRow(ctx, lockTimetableMutationScope, lockKey)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const updateTimetableSlot = `-- name: UpdateTimetableSlot :one
UPDATE timetable_slots
SET assignment_id = $2,
    day_of_week = $3,
    start_time = $4,
    end_time = $5,
    room_label = $6,
    notes = $7,
    updated_at = NOW()
WHERE id = $1
RETURNING id, assignment_id, day_of_week, start_time, end_time, room_label, notes, created_at, updated_at
`

type UpdateTimetableSlotParams struct {
	ID           pgtype.UUID `json:"id"`
	AssignmentID pgtype.UUID `json:"assignment_id"`
	DayOfWeek    int16       `json:"day_of_week"`
	StartTime    pgtype.Time `json:"start_time"`
	EndTime      pgtype.Time `json:"end_time"`
	RoomLabel    string      `json:"room_label"`
	Notes        string      `json:"notes"`
}

func (q *Queries) UpdateTimetableSlot(ctx context.Context, arg UpdateTimetableSlotParams) (TimetableSlot, error) {
	row := q.db.QueryRow(ctx, updateTimetableSlot,
		arg.ID,
		arg.AssignmentID,
		arg.DayOfWeek,
		arg.StartTime,
		arg.EndTime,
		arg.RoomLabel,
		arg.Notes,
	)
	var i TimetableSlot
	err := row.Scan(
		&i.ID,
		&i.AssignmentID,
		&i.DayOfWeek,
		&i.StartTime,
		&i.EndTime,
		&i.RoomLabel,
		&i.Notes,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
